def solve(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    src=None; rects=[]
    for r in range(H):
        for c in range(W):
            col=g[r][c]
            if col==0: continue
            # grow the component
            q=[(r,c)]; comp=set()
            while q:
                x,y=q.pop()
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<H and 0<=ny<W and g[nx][ny]==col and (nx,ny) not in comp:
                        comp.add((nx,ny)); q.append((nx,ny))
            rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
            r1,r2,c1,c2=min(rs),max(rs),min(cs),max(cs)
            h,w=r2-r1+1,c2-c1+1
            if h>=3 and w>=3 and len(comp)==2*(h+w)-4:
                inner=[[g[x][y] for y in range(c1+1,c2)] for x in range(r1+1,r2)]
                n=sum(v!=0 for row in inner for v in row)
                rects.append((r1,c1,r2,c2,col,inner,n))
                if n: src=(r1,c1,r2,c2,col,inner)
    sh,pw=None,None
    si,si_,sj,sj_=src[0],src[1],src[2],src[3]
    sh,sw=len(src[5]),len(src[5][0])
    for r1,c1,r2,c2,col,inner,n in rects:
        ih,iw=len(inner),len(inner[0])
        if (r1,c1,r2,c2)==(si,si_,sj,sj_): continue
        if ih>=sh and iw>=sw:
            for i in range(sh):
                for j in range(sw):
                    if src[5][i][j]:
                        out[r1+1+i][c1+1+j]=col
        else:
            for x in range(r1,r2+1):
                for y in range(c1,c2+1):
