def rects(g):
    H,W=len(g),len(g[0]); out=[]; seen=[[False]*W for _ in range(H)]
    for a in range(H):
        for b in range(W):
            if g[a][b]==0 or seen[a][b]: continue
            col=g[a][b]; q=[(a,b)]; seen[a][b]=True; cells=[]
            while q:
                x,y=q.pop(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<H and 0<=ny<W and g[nx][ny]==col and not seen[nx][ny]:
                        seen[nx][ny]=True; q.append((nx,ny))
            rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
            r1,r2,c1,c2=min(rs),max(rs),min(cs),max(cs); h,w=r2-r1+1,c2-c1+1
            inner=[[g[r][c] for c in range(c1+1,c2)] for r in range(r1+1,r2)]
            out.append(dict(pos=(r1,c1,r2,c2),col=col,h=h,w=w,inner=inner))
    return out
