for nm in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    print(nm, solve(G[nm+' input'])==G[nm+' output'])

def solve(g):
    R=rects(g); out=[row[:] for row in g]
    frames=[r for r in R if r['h']>=3 and r['w']>=3]
    srcs=[f_ for f_ in frames if any(v!=0 for row in f_['inner'] for v in row)]
    tgts=[f_ for f_ in frames if f_ not in srcs]
    def variants(m):
        res=[]; cur=[r[:] for r in m]
        for _ in range(4):
            res.append(tuple(map(tuple,cur)))
            res.append(tuple(map(tuple,[r[::-1] for r in cur])))
            cur=list(zip(*cur))[::-1]
        return res
    for b in tgts:
        ih,iw=b['h']-2,b['w']-2
        best=None
        for s in srcs:
            ph,pw=s['h']-2,s['w']-2
            if ph==ih and pw==iw:
                for var in variants([[v!=0 for v in row] for row in s['inner']]):
                    sc=sum(var[i][j] for i in range(len(var)) for j in range(len(var[0])))
                    if best is None or sc>best[0]: best=(sc,var)
        if best is None:
            for r in range(b['pos'][0],b['pos'][2]+1):
                for c in range(b['pos'][1],b['pos'][3]+1):
                    out[r][c]=0
        else:
            _,var=best
            for i in range(ih):
                for j in range(iw):
                    if var[i][j]:
                        rr,cc=b['pos'][0]+1+i,b['pos'][1]+1+j
                        out[rr][cc]=b['col']
    return out
for nm in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    print(nm, solve(G[nm+' input'])==G[nm+' output'])

o=solve(G['Test input'])
for r_ in o: print(''.join(str(v) if v else '.' for v in r_))
